sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Inter:wght@400;500;600&display=swap');

.qa-section {
  padding: 80px 0;
  background: #ffffff;
  font-family: 'Inter', system-ui, sans-serif;
  color: #2a2d29;
  line-height: 1.6;
  width: 100%;
  box-sizing: border-box;
}

.qa-section *,
.qa-section *::before,
.qa-section *::after {
  box-sizing: border-box;
}

.qa-container {
  width: min(1120px, 92%);
  margin: 0 auto;
}

.qa-section-head {
  text-align: center;
  margin-bottom: 48px;
}

.qa-eyebrow {
  font-size: .72rem;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: #6f756f;
  font-weight: 500;
  display: block;
  margin-bottom: 10px;
}

.qa-section-head h2 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  color: #1f3a30;
  font-weight: 600;
  font-size: clamp(1.9rem, 3vw, 2.5rem);
  line-height: 1.15;
  margin: 0;
}

.qa-divider {
  width: 44px;
  height: 2px;
  background: #d4b07c;
  margin: 16px auto 0;
  border-radius: 2px;
}

.qa-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 26px;
}

.qa-card {
  background: #ffffff;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(31, 58, 48, .08);
  transition: .3s ease;
  border: 1px solid #e7e1d4;
  display: flex;
  flex-direction: column;
  text-decoration: none !important;
  color: inherit;
  min-width: 0;
}

.qa-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 18px 40px rgba(31, 58, 48, .14);
  text-decoration: none !important;
}

.qa-card:focus {
  outline: 2px solid #d4b07c;
  outline-offset: 3px;
}

.qa-card-body {
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  text-align: center;
}

.qa-icon {
  font-size: 2rem;
  line-height: 1.4;
  color: #d4b07c;
}

.qa-card h3 {
  font-family: 'Cormorant Garamond', Georgia, serif;
  color: #1f3a30;
  font-size: 1.4rem;
  font-weight: 600;
  line-height: 1.15;
  margin: 0;
}

.qa-card p {
  color: #6f756f;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: .87rem;
  line-height: 1.6;
  margin: 0;
}

@media (max-width: 900px) {
  .qa-grid {
    grid-template-columns: 1fr;
  }
}
